// 標準入力（左の「入力例」の内容）を 1 つの文字列として受け取り、
// 改行で区切って 1 行ずつの配列にする
const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

// 入力例 1 のとき:
//   input[0] は "{[()()]}"

// 答えは console.log で出力する
// ここに解答を書く

solution.code:
import { readFileSync } from "fs";

const s = readFileSync(0, "utf8").trim();
const pair: Record<string, string> = { ")": "(", "]": "[", "}": "{" };

// まだ閉じていない開き括弧をスタックに積む
const stack: string[] = [];
let ok = true;
for (const c of s) {
  if (c === "(" || c === "[" || c === "{") {
    stack.push(c);
  } else if (stack.pop() !== pair[c]) {
    ok = false; // 対応する開き括弧がない、または種類が違う
    break;
  }
}
console.log(ok && stack.length === 0 ? "Yes" : "No");
